const socket = io('http://localhost:9000');

export default socket;

import { useState, useEffect, useCallback } from 'react';
import './App.css'
import Terminal from './components/terminal'
import FileTree from './components/fileTree';
import socket from './socket';
import AceEditor from "react-ace";

import "ace-builds/src-noconflict/mode-java";
import "ace-builds/src-noconflict/theme-github";
import "ace-builds/src-noconflict/ext-language_tools";
import { use } from 'react';



function App() {

  const [files, setFiles] = useState({});
  const [selectedFile, setSelectedFile] = useState('');
  const [editorContent, setEditorContent] = useState('');
  const [selectedFileContent, setSelectedFileContent] = useState('');
  const saved = selectedFileContent === editorContent;

  const getFileTree = async () => {
    const response = await fetch('http://localhost:9000/files');
    const result = await response.json();
    console.log(result)
    setFiles(result);
  };

  useEffect(() => {
    getFileTree();
  }, []);

  useEffect(() => {
      socket.on('file:change', getFileTree);
      return () => {
          socket.off('file:change', getFileTree);
      }
   }, []);

   useEffect(() => {
    if (editorContent && !saved) {
      const timer = setTimeout(() => {
        socket.emit('file:change', {path: selectedFile, content: editorContent});
      }, 5000);
      return () => clearTimeout(timer);
    };
  }, [editorContent, selectedFile, saved]);

  const getFileContent = useCallback(async () => {
    if (!selectedFile) return;
    const response = await fetch(`http://localhost:9000/file/content/?path=${selectedFile}`);
    const result = await response.json();
    setSelectedFileContent(result.content);
  }, [selectedFile]);

  useEffect(() => {
    if (selectedFile){
      getFileContent();
    }
  }, [selectedFile, getFileContent]);

  useEffect(() => {
    if(selectedFileContent && selectedFile){
      setEditorContent(selectedFileContent);
    }
  }, [selectedFileContent, selectedFile]);

  useEffect(() => {
    setEditorContent("");
  }, [selectedFile]);




  return (
    <>
    <div className='playground-container'>

      <div className='editor-container'>

        <div className='files'>
          <FileTree onSelect = {(path)=>setSelectedFile(path)} tree = {files} />
        </div>

        <div className='editor'>
          { selectedFile && <p>
            {selectedFile.replaceAll('/', " > ")}
            {saved ? " (saved)" : " (unsaved)"}
            </p>}
          <AceEditor 
            value= {editorContent}
            onChange = {(value) => setEditorContent(value)}
          />,
        </div>

      </div>

      <div className='terminal-container'>
        <Terminal />
      </div>
    </div>
    </>
  )
}

export default App

const FileTreeNode = ({filename, nodes, onSelect, path})=>{
    const isDir = !!nodes;
    return (
        <div onClick = {(e)=>{
            e.stopPropagation();
            if(isDir) return;
            onSelect(path);

        }} style = {{marginLeft: 10}}>
            <p className={isDir?"":"file-node"}>{filename}</p>
            {/* {console.log(nodes)} */}
            {nodes && <ul>
                {Object.keys(nodes).map(child => (
                    <li key = {child}>
                        <FileTreeNode filename={child} path={path + "/" + child} nodes = {nodes[child]} onSelect={onSelect}/>
                    </li>
                ))}
                </ul>}
        </div>
    )
}

const FileTree = ({tree, onSelect}) => {
    return (
        <div>
            <FileTreeNode filename="/" path = "" nodes={tree} onSelect={onSelect}/>
        </div>
    )
}

export default FileTree

import { Terminal as XTerminal } from '@xterm/xterm'
import { useEffect, useRef } from 'react'
import '@xterm/xterm/css/xterm.css' 
import socket from '../socket'

export default function Terminal() {
    const terminalRef = useRef()
    const isRendered = useRef(false)

    useEffect(() => {
        if (isRendered.current) return
        isRendered.current = true
        const terminal = new XTerminal({row:40});
        terminal.open(terminalRef.current)

        terminal.onData(data => {
            socket.emit('console:write', data)
        })

        // socket.on('console:data', data => {
        //     terminal.write(data)
        // })

        function onTerminalData(data){
            terminal.write(data)
        }
        socket.on('console:data', data =>{onTerminalData(data)})

        socket.off('console:data', onTerminalData)

    }
    , [])

    return (

        <div ref={terminalRef} id="terminal"></div>
    )
    }
